(
  tlast_over_time(
      kompass_rs_audit_event{
        namespace=~"$namespace",
        resource_id=~"$resource_id",
        audit_event=~"$audit_event",
        execution_state=~"$execution_state",
        optimization_type=~"$optimization_type",
        trace_id=~"$trace_id"
      }[$__range]
  )
  unless on (namespace, resource_id, trace_id, audit_event, optimization_type, execution_state)
  label_replace(
    (
      tlast_over_time(
        kompass_rs_audit_event{
          namespace=~"$namespace",
          resource_id=~"$resource_id",
          audit_event=~"$audit_event",
          execution_state="successful",
          optimization_type=~"$optimization_type",
          trace_id=~"$trace_id"
        }[$__range]
      )
      and on (namespace, resource_id, trace_id, audit_event, optimization_type)
      tlast_over_time(
        kompass_rs_audit_event{
          namespace=~"$namespace",
          resource_id=~"$resource_id",
          audit_event=~"$audit_event",
          execution_state="aborted",
          optimization_type=~"$optimization_type",
          trace_id=~"$trace_id"
        }[$__range]
      )
    ),
    "execution_state", "aborted", "execution_state", "successful"
  )
) * 1000

max by (resource_id, trace_id, execution_state, optimization_type) (
  (
    last_over_time(
      kompass_rs_recommendations{
        namespace=~"$namespace",
        resource_id=~"$resource_id",
